using System;
using System.IO;
using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Web.Script.Serialization;
class DownloadLimiterTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static double Transfer(int size){var listener=new TcpListener(IPAddress.Loopback,53111);listener.Start();var server=new Thread(()=>{try{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){byte[] buffer=new byte[16384];for(int sent=0;sent<size;){int count=Math.Min(buffer.Length,size-sent);stream.Write(buffer,0,count);sent+=count;}}}finally{listener.Stop();}});server.IsBackground=true;server.Start();var watch=Stopwatch.StartNew();using(var client=new TcpClient()){client.ReceiveTimeout=20000;client.Connect(IPAddress.Loopback,53111);using(var stream=client.GetStream()){byte[] buffer=new byte[65536];int received=0;while(received<size){int n=stream.Read(buffer,0,Math.Min(buffer.Length,size-received));if(n==0)throw new IOException("Local download ended early");received+=n;}}}server.Join(2000);return size/Math.Max(.001,watch.Elapsed.TotalSeconds);}
 static int Main(string[] args){try{var pacer=new DownloadPacer(1048576);double wait=0;for(int i=0;i<1024;i++)wait=pacer.Reserve(1024,0);Check(wait>=.974&&wait<=1,"pacing schedules one MiB near one second with bounded burst");Check(pacer.Reserve(1024,10)<.001,"idle time cannot accumulate unlimited burst credit");using(var limiter=new DownloadLimiter()){Check(!limiter.Running,"limiter initially stopped");bool rejected=false;try{limiter.Start("",Double.NaN);}catch(ArgumentException){rejected=true;}Check(rejected,"invalid limit cannot start component");}
 if(Array.IndexOf(args,"--driver")>=0){string id="Local\\ConanBandwidth-"+Guid.NewGuid().ToString("N");using(var stop=new EventWaitHandle(false,EventResetMode.ManualReset,id+"-stop"))using(var ready=new EventWaitHandle(false,EventResetMode.ManualReset,id+"-ready")){
  double before=Transfer(524288);string script;using(DownloadLimiter.VerifyComponents(args[1])){script=LimiterSecurity.Script(args[1],Process.GetCurrentProcess().Id,.1,id).Replace("'"+id+"')","'"+id+"','--test-loopback')");}var p=Process.Start(new ProcessStartInfo(LimiterSecurity.PowerShell,"-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(System.Text.Encoding.Unicode.GetBytes(script))){UseShellExecute=true,Verb="runas",WorkingDirectory=Environment.GetFolderPath(Environment.SpecialFolder.System)});try{bool started=ready.WaitOne(45000);Check(started&&!p.HasExited,"signed driver initialized with loopback-only filter");if(!started||p.HasExited)throw new IOException("Driver test did not start; code "+(p.HasExited?p.ExitCode:-1));double limited=Transfer(524288);Check(limited>=70000&&limited<=135000,"loopback download near 0.1 MiB/s cap");stop.Set();Check(p.WaitForExit(5000)&&p.ExitCode==0,"stop drains queued packets and exits helper");double after=Transfer(524288);Check(after>limited*2,"stopping restores unrestricted loopback throughput");File.WriteAllText(Path.Combine(args[0],"limiter-throughput.json"),new JavaScriptSerializer().Serialize(new{scope="127.0.0.1:53111 only",beforeBytesPerSecond=before,limitedBytesPerSecond=limited,afterBytesPerSecond=after,global_network_throttled=false}));}finally{stop.Set();if(!p.HasExited)p.WaitForExit(5000);p.Dispose();}
 }}
 }catch(Exception e){failures++;Console.WriteLine(e.GetType().Name+" "+e.Message);}Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"limiter-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,driverTest=Array.IndexOf(args,"--driver")>=0}));return failures==0?0:1;}
}
